def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return

    pos = seat.position
    vel = seat.linearVelocity
    speed = math.hypot(vel.x, vel.y)
    target_y = 11.7

    # If already at or above target height, stabilize position to fall into target zone
    if pos.y >= target_y:
        if 9.35 <= pos.x <= 10.65 and speed < 1.0:
            return  # Already in target zone
        else:
            dx = pos.x - 10.0
            if dx > 0.65:
                fx = -42.0
            elif dx < -0.65:
                fx = 42.0
            else:
                # Apply damping to reduce horizontal velocity
                fx = -vel.x * 10.0
            sandbox.apply_force_to_seat(fx, 0)
            return

    # Apply horizontal correction when at apex
    if speed < 1.0:
        dx = pos.x - 10.0
        if dx > 0.65:
            fx = -42.0
        elif dx < -0.65:
            fx = 42.0
        else:
            fx = -vel.x * 10.0
        sandbox.apply_force_to_seat(fx, 0)
        return

    # Apply vertical force at the bottom of the swing to increase energy
    if pos.y < 7.0:
        if vel.y > 0:
            fy = 42.0
        else:
            fy = -42.0
        sandbox.apply_force_to_seat(0, fy)
        return

    # Apply tangent-based force when velocity is aligned with the tangent of the arc
    dx = pos.x - 10.0
    dy = pos.y - 10.0
    tangent_x = -dy
    tangent_y = dx
    dot_product = vel.x * tangent_x + vel.y * tangent_y

    if dot_product > 0:
        mag = math.hypot(tangent_x, tangent_y)
        if mag == 0:
            return
        unit_x = tangent_x / mag
        unit_y = tangent_y / mag
        max_component = max(abs(unit_x), abs(unit_y))
        scale = 42.0 / max_component
        fx = unit_x * scale
        fy = unit_y * scale
        sandbox.apply_force_to_seat(fx, fy)
    else:
        # Apply horizontal correction if not aligned with tangent
        dx = pos.x - 10.0
        if dx > 0:
            fx = -42.0
        elif dx < 0:
            fx = 42.0
        else:
            fx = 0
        sandbox.apply_force_to_seat(fx, 0)

